(() => {
 'use strict';
 const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
 document.documentElement.classList.add('js');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if('IntersectionObserver' in window&&!reduced){const io=new IntersectionObserver(items=>items.forEach(x=>{if(x.isIntersecting){x.target.classList.add('revealed');io.unobserve(x.target)}}),{threshold:.07});$$('[data-reveal]').forEach(x=>io.observe(x));}else $$('[data-reveal]').forEach(x=>x.classList.add('revealed'));
 $$('nav a').forEach(a=>{if(a.getAttribute('href')===location.pathname)a.setAttribute('aria-current','page')});
 const menu=$('#mobile-menu'),toggle=$('.menu-toggle');
 function closeMenu(){menu.hidden=true;toggle.setAttribute('aria-expanded','false');document.body.classList.remove('menu-open')}
 toggle?.addEventListener('click',()=>{const opening=menu.hidden;menu.hidden=!opening;toggle.setAttribute('aria-expanded',String(opening));document.body.classList.toggle('menu-open',opening);if(opening)$('a',menu)?.focus()});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){closeMenu();toggle.focus()}});
 document.addEventListener('keydown',e=>{if(menu.hidden||e.key!=='Tab')return;const links=$$('a',menu);if(e.shiftKey&&document.activeElement===toggle){e.preventDefault();links.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===links.at(-1)){e.preventDefault();toggle.focus()}else if(!e.shiftKey&&document.activeElement===toggle){e.preventDefault();links[0].focus()}});
 matchMedia('(min-width:801px)').addEventListener('change',e=>{if(e.matches)closeMenu()});
 const key='kosova-material-selection-v1';let selected=[];try{const parsed=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(parsed))selected=parsed.filter(x=>typeof x==='string');}catch{}
 let materials=[]; const dataReady=fetch('/materials-data.json').then(r=>{if(!r.ok)throw Error('catalog');return r.json()}).then(data=>{materials=data;selected=selected.filter(id=>materials.some(m=>m.id===id));updateSaved();renderSelection();renderBriefSelection();return data}).catch(()=>{if($('#selection-grid'))$('#selection-empty').hidden=false});
 let toastTimer;function toast(t){const el=$('.toast');el.textContent=t;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2500)}
 function persist(){try{localStorage.setItem(key,JSON.stringify(selected))}catch{toast('Подборка сохранена на время просмотра')}updateSaved()}
 function updateSaved(){$$('[data-count]').forEach(x=>x.textContent=selected.length);$$('[data-save]').forEach(b=>{const saved=selected.includes(b.dataset.save);b.setAttribute('aria-pressed',String(saved));if(b.classList.contains('save-button'))b.textContent=saved?'✓':'+';const l=$('[data-save-label]',b);if(l)l.textContent=saved?'В подборке — убрать':'Добавить в подборку'})}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-save]');if(!b)return;const id=b.dataset.save;const existed=selected.includes(id);selected=existed?selected.filter(x=>x!==id):[...selected,id];persist();renderSelection();renderBriefSelection();toast(existed?'Сочетание убрано из подборки':'Сочетание добавлено в подборку')});
 function renderSelection(){const grid=$('#selection-grid');if(!grid)return;const items=materials.filter(m=>selected.includes(m.id));grid.innerHTML=items.map(m=>`<article class="material-card"><a class="photo-frame" href="/materials/${m.id}/"><img src="/assets/post-${m.image}.jpg" alt="${m.title}" loading="lazy"><span class="material-kind">${m.group}</span></a><button class="save-button" data-save="${m.id}" aria-label="Убрать: ${m.title}" aria-pressed="true">✓</button><div class="card-meta"><span>${m.subtitle}</span></div><h3><a href="/materials/${m.id}/">${m.title}</a></h3></article>`).join('');$('#selection-empty').hidden=items.length>0;$('#selection-actions').hidden=items.length===0}
 $('#clear-selection')?.addEventListener('click',()=>{selected=[];persist();renderSelection();toast('Подборка очищена')});
 function renderBriefSelection(){const el=$('#brief-selection');if(el){const names=materials.filter(m=>selected.includes(m.id)).map(m=>m.title);el.textContent=names.length?`Ваша подборка: ${names.join(', ')}`:''}}
 updateSaved();
 $$('[data-filter-for]').forEach(bar=>{bar.addEventListener('click',e=>{const b=e.target.closest('[data-filter]');if(!b)return;$$('button',bar).forEach(x=>{const active=x===b;x.classList.toggle('active',active);x.setAttribute('aria-pressed',String(active))});if(bar.dataset.filterFor==='projects'){$$('.portfolio-grid .project-card').forEach(c=>{c.hidden=b.dataset.filter!=='Все'&&c.dataset.style!==b.dataset.filter&&c.dataset.type!==b.dataset.filter})}else filterMaterials()})});
 function filterMaterials(){const active=$('[data-filter-for="materials"] .active')?.dataset.filter||'Все';const q=$('#material-search')?.value.toLowerCase().trim()||'';let count=0;$$('.material-library .material-card').forEach(c=>{const show=(active==='Все'||c.dataset.group===active)&&(!q||c.dataset.search.includes(q));c.hidden=!show;if(show)count++});const empty=$('#no-materials');if(empty)empty.hidden=count>0}
 $('#material-search')?.addEventListener('input',filterMaterials);
 const preview=$('.services-preview img');let previewTimer;
 if(preview&&matchMedia('(hover:hover)').matches){$$('[data-preview]').forEach(a=>{a.addEventListener('mouseenter',()=>{clearTimeout(previewTimer);preview.style.opacity='.25';previewTimer=setTimeout(()=>{preview.src=a.dataset.preview;preview.alt=$('h3',a).textContent;preview.onload=()=>preview.style.opacity='1';setTimeout(()=>preview.style.opacity='1',350)},120)})})}
 const form=$('#brief-form');let draft='';
 if(form){const service=new URLSearchParams(location.search).get('service');if(service&&$$('option',form).some(o=>o.value===service))form.elements.service.value=service;
 form.addEventListener('submit',async e=>{e.preventDefault();if(!form.reportValidity())return;await dataReady;const f=new FormData(form);draft=`Здравствуйте! Хочу обсудить проект с Kosova Studio.\n\nИмя: ${f.get('name').trim()}\nКонтакт: ${f.get('contact').trim()}\nГород: ${f.get('city').trim()||'Уточню в диалоге'}\nНаправление: ${f.get('service')}\n\n${f.get('comment').trim()}`;const saved=materials.filter(m=>selected.includes(m.id));if(saved.length)draft+='\n\nПонравившиеся сочетания:\n'+saved.map(m=>`${m.title} — ${location.origin}/materials/${m.id}/`).join('\n');$('#brief-preview').textContent=draft;$('#telegram-brief').href=`https://t.me/yuliakosova86?text=${encodeURIComponent(draft)}`;const result=$('#brief-result');result.hidden=false;result.focus();result.scrollIntoView({behavior:reduced?'auto':'smooth',block:'center'})});
 $('#copy-brief')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(draft);toast('Текст скопирован')}catch{const el=$('#brief-preview');const range=document.createRange();range.selectNodeContents(el);const selection=window.getSelection();selection.removeAllRanges();selection.addRange(range);toast('Текст выделен — скопируйте его')}})}
 const lightbox=$('#lightbox'),gallery=$$('[data-gallery]');let photoIndex=0,lastFocus;
 function showImage(i){photoIndex=(i+gallery.length)%gallery.length;const img=$('img',gallery[photoIndex]);$('img',lightbox).src=img.src;$('img',lightbox).alt=img.alt;$('.lightbox-counter').textContent=`${photoIndex+1} / ${gallery.length} — ${img.alt}`}
 gallery.forEach((b,i)=>b.addEventListener('click',()=>{lastFocus=b;showImage(i);lightbox.showModal();document.body.style.overflow='hidden'}));
 function closeLightbox(){lightbox.close()}
 $('.lightbox-close')?.addEventListener('click',closeLightbox);lightbox?.addEventListener('close',()=>{document.body.style.overflow='';lastFocus?.focus()});$('.lightbox-prev')?.addEventListener('click',()=>showImage(photoIndex-1));$('.lightbox-next')?.addEventListener('click',()=>showImage(photoIndex+1));lightbox?.addEventListener('keydown',e=>{if(e.key==='ArrowRight')showImage(photoIndex+1);if(e.key==='ArrowLeft')showImage(photoIndex-1)});
 let touchStart=0;lightbox?.addEventListener('touchstart',e=>touchStart=e.changedTouches[0].clientX,{passive:true});lightbox?.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>50)showImage(photoIndex+(delta<0?1:-1))},{passive:true});
})();
